"use client";

import { useProjectMembers } from "@/hooks/useProjectMembers";
import { cn } from "@/lib/utils";
import { Hash, MessageCircle, Plus } from "lucide-react";

function UnreadBadge({ count }) {
  if (!count) return null;
  return (
    <span className="shrink-0 min-w-[18px] h-[18px] px-1 rounded-full bg-red-500 text-white text-[10px] flex items-center justify-center">
      {count > 99 ? "99+" : count}
    </span>
  );
}

function PresenceDot({ online }) {
  return (
    <span
      className={cn(
        "w-2 h-2 rounded-full shrink-0",
        online ? "bg-green-500" : "bg-gray-600",
      )}
      title={online ? "Online" : "Offline"}
    />
  );
}

/**
 * Left column: the project's group channel(s), its member roster (click a
 * name to open/start a DM with them), and existing direct-message threads.
 *
 * The roster shown is scoped to whichever channel is currently active — for
 * a client this is always their one project; for admin, switching between
 * projects' group channels switches whose team is listed.
 */
export function ChannelSidebar({
  channels,
  activeChannelId,
  onSelectChannel,
  onStartDirectMessage,
  onOpenTeamPanel,
  currentUserId,
  mobileHidden = false,
}) {
  const groupChannels = channels.filter((c) => c.kind === "group");
  const dmChannels = channels.filter((c) => c.kind === "dm");
  const activeChannel = channels.find((c) => c._id === activeChannelId);
  const rosterProjectId =
    activeChannel?.projectId || groupChannels[0]?.projectId || null;
  const { members } = useProjectMembers(rosterProjectId);

  const otherDmMember = (channel) => {
    const otherUserId = (channel.memberUserIds || []).find(
      (id) => id !== currentUserId,
    );
    return members.find((m) => m.userId === otherUserId) || null;
  };

  return (
    <div
      className={cn(
        "w-full md:w-64 shrink-0 border-r border-white/10 flex-col overflow-y-auto",
        mobileHidden ? "hidden md:flex" : "flex",
      )}
    >
      <div className="p-3">
        <p className="px-2 text-[11px] font-semibold uppercase tracking-wide text-gray-500 mb-1">
          Channels
        </p>
        {groupChannels.map((channel) => (
          <button
            key={channel._id}
            type="button"
            onClick={() => onSelectChannel(channel._id)}
            className={cn(
              "w-full flex items-center gap-2 px-2 py-2 rounded-lg text-sm transition-colors text-left",
              channel._id === activeChannelId
                ? "bg-[#FFB633] text-black"
                : "text-gray-300 hover:bg-white/5",
            )}
          >
            <Hash className="w-4 h-4 shrink-0" />
            <span className="truncate flex-1">
              {channel.name || "Project Group"}
            </span>
            <UnreadBadge count={channel.unreadCount} />
          </button>
        ))}
      </div>

      {rosterProjectId && (
        <div className="p-3 border-t border-white/10">
          <div className="flex items-center justify-between px-2 mb-1">
            <p className="text-[11px] font-semibold uppercase tracking-wide text-gray-500">
              Members
            </p>
            {onOpenTeamPanel && (
              <button
                type="button"
                onClick={() => onOpenTeamPanel(rosterProjectId)}
                className="flex items-center gap-0.5 px-2 py-0.5 rounded-full border border-[#FFB633] text-[#FFB633] text-[10px] font-medium hover:bg-[#FFB633]/10 transition-colors"
                title="Add team member"
              >
                <Plus className="w-3 h-3" /> Add
              </button>
            )}
          </div>
          {members.map((m) => {
            const isSelf = m.userId === currentUserId;
            return (
              <button
                key={m.userId}
                type="button"
                onClick={() =>
                  !isSelf &&
                  onStartDirectMessage?.({
                    projectId: rosterProjectId,
                    userId: m.userId,
                  })
                }
                disabled={isSelf}
                className="w-full flex items-center gap-2 px-2 py-1.5 rounded-lg text-sm text-gray-300 hover:bg-white/5 disabled:opacity-50 disabled:cursor-default text-left"
              >
                <PresenceDot online={m.isOnline} />
                <span className="truncate flex-1">
                  {m.name}
                  {isSelf ? " (you)" : ""}
                </span>
                <span className="text-[10px] text-gray-500 shrink-0">
                  {m.roleLabel}
                </span>
              </button>
            );
          })}
        </div>
      )}

      <div className="p-3 border-t border-white/10">
        <p className="px-2 text-[11px] font-semibold uppercase tracking-wide text-gray-500 mb-1">
          Direct
        </p>
        {dmChannels.length === 0 ? (
          <p className="px-2 text-xs text-gray-600">No direct messages yet</p>
        ) : (
          dmChannels.map((channel) => {
            const other = otherDmMember(channel);
            return (
              <button
                key={channel._id}
                type="button"
                onClick={() => onSelectChannel(channel._id)}
                className={cn(
                  "w-full flex items-center gap-2 px-2 py-2 rounded-lg text-sm transition-colors text-left",
                  channel._id === activeChannelId
                    ? "bg-[#FFB633] text-black"
                    : "text-gray-300 hover:bg-white/5",
                )}
              >
                <MessageCircle className="w-4 h-4 shrink-0" />
                <PresenceDot online={other?.isOnline} />
                <span className="truncate flex-1">
                  {other?.name || "Direct message"}
                </span>
                <UnreadBadge count={channel.unreadCount} />
              </button>
            );
          })
        )}
      </div>
    </div>
  );
}

export default ChannelSidebar;

'use client';

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import axios from 'axios';
import { useAuth } from './useAuth';

// Team roster + invitations for one project. GET /api/client-projects/:id/members
// already scopes pending invitations to whoever can invite, and private
// emails to owner/admin — this hook just exposes what the server returns.
export function useProjectMembers(projectId) {
  const queryClient = useQueryClient();
  const { getAuthHeaders } = useAuth();

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: ['project-members', projectId] });
  };

  const membersQuery = useQuery({
    queryKey: ['project-members', projectId],
    enabled: !!projectId,
    queryFn: async () => {
      const res = await axios.get(
        `/api/client-projects/${projectId}/members`,
        { headers: getAuthHeaders() },
      );
      return res.data; // { members, invitations }
    },
  });

  const invite = useMutation({
    mutationFn: async (data) => {
      // { email, intendedRole, roleLabel?, personalMessage? }
      const res = await axios.post(
        `/api/client-projects/${projectId}/invitations`,
        data,
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: invalidate,
  });

  const resendInvitation = useMutation({
    mutationFn: async (invitationId) => {
      const res = await axios.post(
        `/api/client-projects/${projectId}/invitations/${invitationId}/resend`,
        {},
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: invalidate,
  });

  const revokeInvitation = useMutation({
    mutationFn: async (invitationId) => {
      const res = await axios.delete(
        `/api/client-projects/${projectId}/invitations/${invitationId}`,
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: invalidate,
  });

  const updateMember = useMutation({
    mutationFn: async ({ memberId, data }) => {
      // data: { role?, roleLabel? }
      const res = await axios.patch(
        `/api/client-projects/${projectId}/members/${memberId}`,
        data,
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: invalidate,
  });

  const removeMember = useMutation({
    mutationFn: async (memberId) => {
      const res = await axios.delete(
        `/api/client-projects/${projectId}/members/${memberId}`,
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: invalidate,
  });

  // The owner has no leaveProject permission (there is no membership row for
  // them to leave) — the server rejects that with 403, this hook doesn't
  // special-case it.
  const leaveProject = useMutation({
    mutationFn: async () => {
      const res = await axios.post(
        `/api/client-projects/${projectId}/leave`,
        {},
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: () => {
      invalidate();
      queryClient.invalidateQueries({ queryKey: ['client-projects'] });
      queryClient.invalidateQueries({ queryKey: ['chat-channels'] });
    },
  });

  return {
    members: membersQuery.data?.members || [],
    invitations: membersQuery.data?.invitations || [],
    isLoading: membersQuery.isLoading,
    error: membersQuery.error,
    invite,
    resendInvitation,
    revokeInvitation,
    updateMember,
    removeMember,
    leaveProject,
  };
}

'use client';

import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import axios from 'axios';
import { useAuth } from './useAuth';

// Every channel visible to the caller, with unread count and a last-message
// preview already attached (GET /api/chat/channels does the lazy group-
// channel creation and the DM privacy filtering server-side — this hook is a
// thin wrapper).
export function useChatChannels() {
  const queryClient = useQueryClient();
  const { getAuthHeaders } = useAuth();

  const channelsQuery = useQuery({
    queryKey: ['chat-channels'],
    refetchInterval: 15000,
    queryFn: async () => {
      const res = await axios.get('/api/chat/channels', {
        headers: getAuthHeaders(),
      });
      return res.data;
    },
  });

  // Get-or-create a direct message with a fellow project participant. The
  // server rejects a target with no relationship to the project — this is
  // not a way to message an arbitrary stranger.
  const startDirectMessage = useMutation({
    mutationFn: async ({ projectId, userId }) => {
      const res = await axios.post(
        '/api/chat/dm',
        { projectId, userId },
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: () =>
      queryClient.invalidateQueries({ queryKey: ['chat-channels'] }),
  });

  return {
    channels: channelsQuery.data || [],
    isLoading: channelsQuery.isLoading,
    error: channelsQuery.error,
    startDirectMessage,
  };
}

// Pinned messages for one channel — its own small query since the pinned bar
// (Section 11) renders independently of the main scroll-back thread below.
export function useChatPinned(channelId) {
  const { getAuthHeaders } = useAuth();
  const pinnedQuery = useQuery({
    queryKey: ['chat-pinned', channelId],
    enabled: !!channelId,
    queryFn: async () => {
      const res = await axios.get(`/api/chat/channels/${channelId}/pinned`, {
        headers: getAuthHeaders(),
      });
      return res.data;
    },
  });
  return {
    pinned: pinnedQuery.data || [],
    isLoading: pinnedQuery.isLoading,
  };
}

// One channel's message thread, with backward pagination for scroll-up
// history, plus every mutation the composer/message list needs.
//
// Pages are fetched newest-first (page 0 = latest 50, oldest-first within
// that batch); `getNextPageParam` asks the server for whatever is older than
// the oldest message currently loaded. `messages` below un-reverses the page
// order so the caller always gets one flat, oldest-to-newest array.
export function useChatMessages(channelId, { flag, q } = {}) {
  const queryClient = useQueryClient();
  const { getAuthHeaders } = useAuth();

  const invalidate = () => {
    // A prefix match: invalidates every {flag, q} variant of this channel's
    // messages, not just the one currently on screen.
    queryClient.invalidateQueries({ queryKey: ['chat-messages', channelId] });
    queryClient.invalidateQueries({ queryKey: ['chat-channels'] });
  };

  const messagesQuery = useInfiniteQuery({
    queryKey: ['chat-messages', channelId, { flag: flag || 'all', q: q || '' }],
    enabled: !!channelId,
    refetchInterval: 4000,
    staleTime: 0,
    refetchOnMount: 'always',
    initialPageParam: null,
    queryFn: async ({ pageParam }) => {
      const params = new URLSearchParams();
      if (pageParam) params.set('before', pageParam);
      if (flag && flag !== 'all') {
        // "attachment:image"/"attachment:document" are the one filter value
        // that isn't a message flag — translate to the server's separate
        // attachmentType param (image|pdf) instead of sending it as `flag`.
        if (flag.startsWith('attachment:')) {
          params.set(
            'attachmentType',
            flag === 'attachment:image' ? 'image' : 'pdf',
          );
        } else {
          params.set('flag', flag);
        }
      }
      if (q) params.set('q', q);
      const res = await axios.get(
        `/api/chat/channels/${channelId}/messages?${params.toString()}`,
        { headers: getAuthHeaders() },
      );
      return res.data; // oldest-first within this page
    },
    // A page shorter than the server's limit (50) means there is nothing
    // older left to fetch.
    getNextPageParam: (lastPage) => {
      if (!Array.isArray(lastPage) || lastPage.length < 50) return undefined;
      return lastPage[0]?.createdAt;
    },
  });

  // pages[0] is the newest batch (fetched first), pages[N] the oldest
  // (fetched last via fetchNextPage) — reverse the page order, keep each
  // page's own oldest-first order, to get one chronological array.
  const messages = (messagesQuery.data?.pages || [])
    .slice()
    .reverse()
    .flat();

  const sendMessage = useMutation({
    mutationFn: async (data) => {
      const res = await axios.post(
        `/api/chat/channels/${channelId}/messages`,
        data,
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: invalidate,
  });

  const editMessage = useMutation({
    mutationFn: async ({ messageId, body }) => {
      const res = await axios.patch(
        `/api/chat/messages/${messageId}`,
        { body },
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: invalidate,
  });

  const deleteMessage = useMutation({
    mutationFn: async (messageId) => {
      const res = await axios.delete(`/api/chat/messages/${messageId}`, {
        headers: getAuthHeaders(),
      });
      return res.data;
    },
    onSuccess: invalidate,
  });

  const togglePin = useMutation({
    mutationFn: async ({ messageId, pinned }) => {
      const res = await axios.post(
        `/api/chat/messages/${messageId}/pin`,
        { pinned },
        { headers: getAuthHeaders() },
      );
      return res.data;
    },
    onSuccess: () => {
      invalidate();
      queryClient.invalidateQueries({ queryKey: ['chat-pinned', channelId] });
    },
  });

